{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for this S3 bucket. Without access logging, it is difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled for this S3 bucket. Without versioning, it is not possible to recover from accidental deletions or overwrites of objects."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server-side encryption enabled with a KMS key. This increases the risk of data exposure if the bucket is compromised."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"financials\" {\n  bucket        = \"${local.resource_prefix.value}-financials\"\n  acl           = \"private\"\n  force_destroy = true\n\n  tags = merge({\n    Name        = \"${local.resource_prefix.value}-financials\"\n    Environment = local.resource_prefix.value\n  }, {})\n\n  logging {\n    target_bucket = \"${local.resource_prefix.value}-logs\"\n    target_prefix = \"${local.resource_prefix.value}/financials/\"\n  }\n\n  versioning {\n    enabled = true\n  }\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        sse_algorithm     = \"aws:kms\"\n      }\n    }\n  }\n}",
  "fix_summary": "Enabled access logging, versioning, and server-side encryption with KMS for the S3 bucket to improve security and compliance."
}
